INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('yearly', 'event', 'الإكثار من الصيام في المحرم، وصوم عاشوراء ومعه التاسع', 'Veelvuldig vasten in Muharram, en het vasten van 3aashoeraa'' samen met de negende dag.', 'Abundant fasting in Muharram, and fasting 3aashooraa'' together with the ninth.', 'وأثر الصحابة: كانوا يصوّمونه صبيانهم ويجعلون لهم اللعبة من العهن يلهونهم بها حتى الإفطار [البخاري (1960)، ومسلم (1136)].', 'En het doen van de metgezellen: zij lieten hun kinderen het vasten en maakten voor hen een speeltje van wol om hen tot de iftaar bezig te houden [al-Bukhaarie 1960].', 'And the companions'' practice: they made their children fast and made them a toy of wool to distract them until iftaar [al-Bukhaaree 1960].', 'الأجر منصوص: تكفير السنة الماضية.', 'De beloning is uitdrukkelijk: het uitwissen van het voorbije jaar.', 'The reward is stated: the expiation of the past year.', 'صيام المحرم وعاشوراء', 'jaarlijkse periode', 'yearly season', 1, 301),('yearly', 'event', 'الإكثار من الصيام في شعبان، وأما ليلة النصف فيُرجى فضل المغفرة فيها لمن سلم من الشرك والشحناء، من غير تخصيصها بقيام ولا يومها بصيام', 'Veelvuldig vasten in Sha3baan; en in de nacht van de vijftiende wordt de vergeving gehoopt voor wie vrij is van shirk en vijandschap, zonder haar met iets bijzonders te onderscheiden.', 'Abundant fasting in Sha3baan; and on the night of the fifteenth forgiveness is hoped for whoever is free of shirk and enmity, without singling it out with anything special.', 'من كانت له عادة قيام أو صيام أتى بها في النصف كغيره من غير اعتقاد خصوصية.', 'Wie een gewoonte van nachtwake of vasten heeft, verricht die op de vijftiende zoals op andere (dagen), zonder een bijzonderheid te geloven.', 'Whoever has a habit of night prayer or fasting performs it on the fifteenth as on others, without believing in a peculiarity.', 'الفضل منصوص في حديث الاطلاع: مغفرة عامة إلا لمشرك أو مشاحن.', 'De verdienste is uitdrukkelijk in de hadieth van het neerdalen (van Allaah): een algemene vergeving, behalve voor een moeshrik of iemand die haat koestert.', 'The merit is stated in the hadeeth of the descent: a general forgiveness, except for a mushrik or one bearing rancour.', 'صيام شعبان', 'jaarlijkse periode', 'yearly season', 1, 302),('yearly', 'event', 'صيامه، وقيامه، وتلاوة القرآن، والجود، والاعتكاف وتحري ليلة القدر في عشره الأواخر بدعائها المتقدم', 'Ramadaan: zijn vasten en nachtgebed, de recitatie en vrijgevigheid, en de i3tikaaf met het zoeken van laylatu-l-qadr in de laatste tien nachten met haar smeekbede.', 'Ramadaan: its fasting and night prayer, recitation and generosity, and i3tikaaf seeking laylatu-l-qadr in the last ten nights with its supplication.', 'ومن هديه فيه مدارسة القرآن كل ليلة والجود بالخير حتى يكون كالريح المرسلة [البخاري (6)].', 'En tot zijn leidraad erin behoort het dagelijks bestuderen van de Koran en de vrijgevigheid met het goede, tot hij als de gezonden wind wordt [al-Bukhaarie 6].', 'And of his guidance in it is studying the Koran nightly and generosity with good, until he becomes like the sent wind [al-Bukhaaree 6].', 'مغفرة ما تقدم لمن صامه وقامه إيمانا واحتسابا، وليلة القدر خير من ألف شهر.', 'Vergeving van wat voorbij is voor wie het vast en er in nachtwake bij staat uit geloof en hoop op beloning; en laylatu-l-qadr is beter dan duizend maanden.', 'Forgiveness of what has passed for whoever fasts it and stands in its night out of faith and hope of reward; and laylatu-l-qadr is better than a thousand months.', 'إحياء رمضان وليلة القدر', 'jaarlijkse periode', 'yearly season', 1, 303),('yearly', 'event', 'ست أيام من شوال، متتابعة أو مفرقة', 'Zes dagen van Shawwaal, aaneengesloten of verspreid.', 'Six days of Shawwaal, consecutive or spread out.', 'تفريقها في الشهر أرفق، وتتابعها أسرع إبراء للذمة من العزيمة.', 'Ze over de maand verspreiden is gemakkelijker, en ze aaneengesloten (vasten) kwijt de plicht sneller uit vastberadenheid.', 'Spreading them over the month is easier, and fasting them consecutively discharges the duty sooner out of resolve.', 'الأجر منصوص: كصيام الدهر؛ رمضان بعشرة أشهر والست بشهرين.', 'De beloning is uitdrukkelijk: als het vasten van het hele jaar; Ramadaan telt als tien maanden en de zes (dagen) als twee maanden.', 'The reward is stated: like fasting the whole year; Ramadaan counts as ten months and the six (days) as two months.', 'صيام ست من شوال', 'jaarlijkse periode', 'yearly season', 1, 304),('yearly', 'event', 'الإكثار من التهليل والتكبير والتحميد، والتكبير المطلق والمقيد، وصوم عرفة لغير الحاج ــ تقدم تفصيله بآثاره في بابه ــ', 'De tien dagen van Dhu-l-hidjdjah: veelvuldige tahliel, takbier en tahmied, de vrije en de gebonden takbier, en het vasten van 3arafah voor de niet-bedevaartganger.', 'The ten days of Dhu-l-hijjah: abundant tahleel, takbeer and tahmeed, the unrestricted and restricted takbeer, and fasting 3arafah for the non-pilgrim.', 'ويجمع في العشر بين الذكر والصيام والصدقة والأضحية لمن قدر.', 'Men combineert in de tien dagen de dhikr, het vasten, de liefdadigheid en het offer voor wie kan.', 'One combines in the ten days the dhikr, fasting, charity and sacrifice for whoever is able.', 'صوم عرفة يكفر سنتين، وما من أيام العمل الصالح فيهن أحب إلى الله من العشر [البخاري (969)].', 'Het vasten van 3arafah wist twee jaren uit, en er zijn geen dagen waarop de goede daad Allaah liefeer is dan de tien [al-Bukhaarie 969].', 'Fasting 3arafah expiates two years, and there are no days in which good deeds are dearer to Allaah than the ten [al-Bukhaaree 969].', 'عمل عشر ذي الحجة', 'jaarlijkse periode', 'yearly season', 1, 305),('quran_duas', 'event', '﴿رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ ۝١٢٧ رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ﴾', 'Vertaling van de betekenis: Onze Heer, aanvaard van ons; U bent de Alhorende, de Alwetende. Onze Heer, maak ons beiden aan U overgegeven en maak uit ons nageslacht een gemeenschap die aan U is overgegeven, en aanvaard ons berouw; U bent de al-Berouwaanvaardende (at-Tawwaab), de al-Genadevolle (ar-Rahiem).', 'Meaning: Our Lord, accept from us; You are the All-Hearing, the All-Knowing. Our Lord, make us both submissive to You and of our descendants a nation submissive to You, and accept our repentance; You are at-Tawwaab (the Accepter of repentance), ar-Raheem (the Bestower of Mercy).', 'قالها إبراهيم وإسماعيل عليهما السلام وهما يرفعان القواعد من البيت؛ فتقال عند إتمام كل عمل صالح: بناء مسجد، وختم كتاب، وفراغ من مشروع خير؛ خوفَ الرد ورجاءَ القبول.', 'Ibraahiem en Ismaa3iel (vrede zij met hen) zeiden haar terwijl zij de fundamenten van het Huis optrokken; zij wordt dus gezegd bij de voltooiing van elke goede daad: het bouwen van een moskee, het afronden van een boek, of het einde van een goed werk.', 'Ibraaheem and Ismaa3eel (peace be upon them) said it while raising the foundations of the House; so it is said at the completion of every good deed: building a mosque, finishing a book, or the end of a good work.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء إبراهيم عند بناء البيت', 'onbeperkt', 'unrestricted', 1, 306),('quran_duas', 'event', '﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾', 'Vertaling van de betekenis: Onze Heer, schenk ons in dit leven het goede en in het Hiernamaals het goede, en bescherm ons tegen de bestraffing van het Vuur.', 'Meaning: Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'بين الركن اليماني والحجر الأسود', 'onbeperkt', 'unrestricted', 1, 307),('quran_duas', 'event', '﴿رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾', 'Vertaling van de betekenis: Onze Heer, stort geduld over ons uit, maak onze voeten standvastig en help ons tegen het ongelovige volk.', 'Meaning: Our Lord, pour patience upon us, make firm our feet, and help us against the disbelieving people.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالصبر والثبات', 'onbeperkt', 'unrestricted', 1, 308),('quran_duas', 'event', '﴿رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾', 'Vertaling van de betekenis: Onze Heer, reken het ons niet aan als wij vergeten of fouten maken. Onze Heer, leg ons geen last op zoals U die oplegde aan hen vóór ons. Onze Heer, belast ons niet met wat wij niet kunnen dragen. Scheld ons kwijt, vergeef ons en wees ons genadig. U bent onze Beschermheer; help ons dus tegen het ongelovige volk.', 'Meaning: Our Lord, do not take us to task if we forget or err. Our Lord, do not lay upon us a burden like that You laid upon those before us. Our Lord, do not burden us with what we cannot bear. Pardon us, forgive us and have mercy on us. You are our Protector, so help us against the disbelieving people.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بعد تمام الإيمان', 'onbeperkt', 'unrestricted', 1, 309),('quran_duas', 'event', '﴿رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ الْوَهَّابُ﴾', 'Vertaling van de betekenis: Onze Heer, laat onze harten niet afwijken nadat U ons heeft geleid, en schenk ons barmhartigheid van bij U; waarlijk, U bent de Milde Schenker.', 'Meaning: Our Lord, let not our hearts deviate after You have guided us, and grant us mercy from Yourself; indeed You are the Bestower.', 'هي دعاء الراسخين في العلم عند المتشابهات؛ فتقال عند الفتن والشبهات وتقلب الأحوال.', 'Zij is de smeekbede van de standvastigen in kennis bij de meerduidige (verzen); zij wordt dus gezegd bij beproevingen, twijfels en het wisselen van toestanden.', 'It is the supplication of those firm in knowledge at the ambiguous (verses); so it is said at trials, doubts and the changing of states.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالثبات على الهدى', 'onbeperkt', 'unrestricted', 1, 310),('quran_duas', 'event', '﴿رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ﴾', 'Vertaling van de betekenis: Onze Heer, waarlijk, wij geloven; vergeef ons dus onze zonden en bescherm ons tegen de bestraffing van het Vuur.', 'Meaning: Our Lord, indeed we believe, so forgive us our sins and protect us from the punishment of the Fire.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء أولي الألباب', 'onbeperkt', 'unrestricted', 1, 311),('quran_duas', 'event', '﴿رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ﴾', 'Vertaling van de betekenis: Mijn Heer, schenk mij van bij U een goed nageslacht; waarlijk, U bent de Verhoorder van de smeekbede.', 'Meaning: My Lord, grant me from Yourself good offspring; indeed You are the Hearer of supplication.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالذرية الطيبة', 'onbeperkt', 'unrestricted', 1, 312),('quran_duas', 'event', '﴿رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾', 'Vertaling van de betekenis: Onze Heer, vergeef ons onze zonden en onze buitensporigheid in onze zaak, maak onze voeten standvastig en help ons tegen het ongelovige volk.', 'Meaning: Our Lord, forgive us our sins and our excesses in our affair, make firm our feet, and help us against the disbelieving people.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بمغفرة الذنب والإسراف', 'onbeperkt', 'unrestricted', 1, 313),('quran_duas', 'event', '﴿رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ﴾', 'Vertaling van de betekenis: Onze Heer, wij hebben onszelf onrecht aangedaan; en als U ons niet vergeeft en ons niet genadig bent, behoren wij zeker tot de verliezers — de smeekbede van Aadam en Hawwaa''.', 'Meaning: Our Lord, we have wronged ourselves; and if You do not forgive us and have mercy on us, we shall surely be among the losers — the supplication of Aadam and Hawwaa''.', 'قالها آدم وحواء عليهما السلام عقب الذنب فتاب الله عليهما؛ فهي دعاء التائبين أثر كل خطيئة.', 'Aadam en Hawwaa'' (vrede zij met hen) zeiden haar na de zonde en Allaah aanvaardde hun berouw; zij is dus de smeekbede van de berouwvollen na elke misstap.', 'Aadam and Hawwaa'' (peace be upon them) said it after the sin and Allaah accepted their repentance; so it is the supplication of the repentant after every lapse.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء آدم عند الزلل', 'onbeperkt', 'unrestricted', 1, 314),('quran_duas', 'event', '﴿أَنتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الْغَافِرِينَ ۝١٥٥ وَاكْتُبْ لَنَا فِي هَذِهِ الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ إِنَّا هُدْنَا إِلَيْكَ﴾', 'Vertaling van de betekenis: U bent onze Beschermheer; vergeef ons dus en wees ons genadig, en U bent de Beste der vergevers. En schrijf voor ons het goede voor in dit leven en in het Hiernamaals; waarlijk, wij zijn tot U teruggekeerd.', 'Meaning: You are our Protector, so forgive us and have mercy on us, and You are the best of forgivers. And decree for us good in this world and in the Hereafter; indeed we have turned back to You.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالمغفرة والرحمة', 'onbeperkt', 'unrestricted', 1, 315),('quran_duas', 'event', '﴿فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ﴾', 'Vertaling van de betekenis: Schepper van de hemelen en de aarde, U bent mijn Beschermheer in dit leven en het Hiernamaals; neem mij weg als moslim en voeg mij bij de rechtschapenen — de smeekbede van Yoesuf bij de voltooiing van de gunst.', 'Meaning: Originator of the heavens and the earth, You are my Protector in this world and the Hereafter; take me in death as a Muslim and join me with the righteous — Yoesuf''s supplication at the completion of favour.', 'قالها يوسف عليه السلام عند تمام الملك واجتماع الشمل؛ فتقال عند ذروة النعم سؤالا لحسن الخاتمة؛ لئلا تطغي النعمة.', 'Yoesuf (vrede zij met hem) zei haar bij de voltooiing van het koningschap en de hereniging; zij wordt dus gezegd op het hoogtepunt van de gunsten, vragend om een goed einde, opdat de gunst niet doet overmoedigen.', 'Yoosuf (peace be upon him) said it at the completion of kingship and reunion; so it is said at the peak of blessings, asking for a good end, lest the favour cause insolence.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بحسن الخاتمة', 'onbeperkt', 'unrestricted', 1, 316),('quran_duas', 'event', '﴿رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ ۝٤٠ رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ﴾', 'Vertaling van de betekenis: Mijn Heer, maak mij een onderhouder van het gebed, en ook uit mijn nageslacht; onze Heer, en aanvaard mijn smeekbede. Onze Heer, vergeef mij en mijn ouders en de gelovigen op de Dag waarop de afrekening plaatsvindt.', 'Meaning: My Lord, make me an establisher of prayer, and from my descendants too; our Lord, and accept my supplication. Our Lord, forgive me and my parents and the believers on the Day the reckoning takes place.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بإقامة الصلاة', 'onbeperkt', 'unrestricted', 1, 317),('quran_duas', 'event', '﴿رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا﴾', 'Vertaling van de betekenis: Mijn Heer, wees hen beiden genadig, zoals zij mij als kleine hebben opgevoed.', 'Meaning: My Lord, have mercy on them both as they raised me when I was small.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء للوالدين', 'onbeperkt', 'unrestricted', 1, 318),('quran_duas', 'event', '﴿رَّبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا﴾', 'Vertaling van de betekenis: Mijn Heer, laat mij binnentreden met een waarachtige intrede en laat mij uitgaan met een waarachtige uitgang, en schenk mij van bij U een helpende macht.', 'Meaning: My Lord, cause me to enter a sound entrance and to exit a sound exit, and grant me from Yourself a supporting authority.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بصدق المدخل والمخرج', 'onbeperkt', 'unrestricted', 1, 319),('quran_duas', 'event', '﴿رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا﴾', 'Vertaling van de betekenis: Onze Heer, schenk ons barmhartigheid van bij U en bereid voor ons in onze zaak een juiste leiding voor — de smeekbede van de mensen van de grot.', 'Meaning: Our Lord, grant us mercy from Yourself and prepare for us right guidance in our affair — the supplication of the people of the cave.', 'دعاء من جاء بعد الصحابة؛ فهو ورد المؤمن للسابقين بالإيمان، ويقال عند فتن الطعن في الصحابة خاصة: طلبا لسلامة القلب من الغل لهم.', 'De smeekbede van wie na de metgezellen kwam; het is de wird van de gelovige voor wie hem in het geloof voorgingen, en wordt gezegd bij beproevingen van het bekritiseren van de metgezellen in het bijzonder: vragend om een zuiver hart jegens hen.', 'The supplication of those who came after the companions; it is the believer''s wird for those who preceded him in faith, said especially at trials of criticising the companions: asking for a heart sound toward them.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء عند الفتنة', 'onbeperkt', 'unrestricted', 1, 320);